DO $$
BEGIN
    IF to_regclass('digest.digest_subscriptions') IS NOT NULL AND to_regclass('digest.digest_digests') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('digest.digest_subscriptions') AND c.contype = 'f' AND a.attname = 'digest_id'
    ) THEN
        ALTER TABLE digest.digest_subscriptions ADD CONSTRAINT fk_digest_subscriptions_digest_id FOREIGN KEY (digest_id) REFERENCES digest.digest_digests (id) ON DELETE CASCADE NOT VALID;
        BEGIN
            ALTER TABLE digest.digest_subscriptions VALIDATE CONSTRAINT fk_digest_subscriptions_digest_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_digest_subscriptions_digest_id left NOT VALID: stored rows of digest.digest_subscriptions reference missing rows';
        END;
    END IF;
END $$;

